package com.android.messaging.ui.conversation;import android.view.LayoutInflater;import android.view.ViewGroup;import android.support.annotation.NonNull;import android.support.v7.widget.RecyclerView;import com.android.messaging.R;import com.android.messaging.sms.SmsRepository;import java.util.ArrayList;import java.util.List;
public final class ConversationMessageAdapter extends RecyclerView.Adapter<ConversationMessageAdapter.H>{public interface Host{void menu(SmsRepository.Message m);}private final String address;private final Host host;private final ArrayList<SmsRepository.Message>items=new ArrayList<>();public ConversationMessageAdapter(String a,Host h){address=a;host=h;}public void setItems(List<SmsRepository.Message>x){items.clear();if(x!=null)items.addAll(x);notifyDataSetChanged();}@NonNull public H onCreateViewHolder(@NonNull ViewGroup p,int t){ConversationMessageView v=(ConversationMessageView)LayoutInflater.from(p.getContext()).inflate(R.layout.conversation_message_view,p,false);return new H(v);}public void onBindViewHolder(@NonNull H h,int p){SmsRepository.Message m=items.get(p);h.v.bind(m,address);h.v.setOnLongClickListener(v->{host.menu(m);return true;});}public int getItemCount(){return items.size();}static final class H extends RecyclerView.ViewHolder{final ConversationMessageView v;H(ConversationMessageView x){super(x);v=x;}}}
